```js
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const DEFAULTS = { port: 3000, host: 'localhost' };
const CONFIG_PATH = path.join(path.dirname(fileURLToPath(import.meta.url)), 'config.json');

export function loadConfig() {
  const fileConfig = existsSync(CONFIG_PATH)
    ? JSON.parse(readFileSync(CONFIG_PATH, 'utf8'))
    : {};

  const envConfig = {};
  if (process.env.APP_PORT !== undefined) envConfig.port = Number(process.env.APP_PORT);
  if (process.env.APP_HOST !== undefined) envConfig.host = process.env.APP_HOST;

  return { ...DEFAULTS, ...fileConfig, ...envConfig };
}
